import json, os
for f in ['eval_object_scalar_seed45_r2.json', 'eval_object_random_selection_seed42.json', 'eval_object_obs_only.json', 'eval_object_vla_only_seed44.json', 'eval_mag_obsonly_norm003.json']:
    path = f'/root/acr-vla-conformal-refinement/logs/{f}'
    if os.path.exists(path):
        d = json.load(open(path))
        sr = d.get('success_rate', d.get('overall_success_rate', 'N/A'))
        print(f'{f}: SR={sr}')
        if 'per_task_success_rates' in d:
            for t,v in d['per_task_success_rates'].items():
                print(f'  {t}: {v}')
        print()
